mod common;
use common::*;
use codenotch_gemini_experimental::{ingress::*,contract::*,Error};
#[derive(Default)] struct Memory {data:Option<CacheState>,fail:bool}
impl CacheStore for Memory {fn load(&self)->Result<Option<CacheState>,Error>{Ok(self.data.clone())}fn commit(&mut self,state:&CacheState)->Result<(),Error>{if self.fail {return Err(Error::Io);}self.data=Some(state.clone());Ok(())}}
fn message(seq:u64)->Vec<u8>{serde_json::to_vec(&Envelope {transport_version:1,pairing_generation:GENERATION.into(),sequence:seq,nonce:format!("{seq:032x}"),sent_at_ms:NOW,payload:snapshot()}).unwrap()}
#[test] fn sequenced_submission_and_original_timestamp() {let mut m=Memory::default();let mut i=Ingress::new(GENERATION,&m).unwrap();assert_eq!(i.submit(&message(1),NOW+100,&mut m),Ok(Ack {sequence:1}));assert_eq!(i.latest().unwrap().snapshot.observed_at_ms,NOW);assert_eq!(i.latest().unwrap().received_at_ms,NOW+100);}
#[test] fn replay_is_rejected_after_restart() {let mut m=Memory::default();let mut i=Ingress::new(GENERATION,&m).unwrap();i.submit(&message(1),NOW,&mut m).unwrap();let mut reopened=Ingress::new(GENERATION,&m).unwrap();assert_eq!(reopened.submit(&message(1),NOW,&mut m),Err(Error::Replay));assert_eq!(reopened.latest().unwrap().display_state(NOW),Status::Historical);}
#[test] fn nonce_reuse_rejected() {let mut m=Memory::default();let mut i=Ingress::new(GENERATION,&m).unwrap();i.submit(&message(1),NOW,&mut m).unwrap();let mut v:serde_json::Value=serde_json::from_slice(&message(2)).unwrap();v["nonce"]=format!("{:032x}",1).into();assert_eq!(i.submit(&serde_json::to_vec(&v).unwrap(),NOW,&mut m),Err(Error::Replay));}
#[test] fn generation_mismatch_rejected() {let mut m=Memory::default();let mut i=Ingress::new(GENERATION,&m).unwrap();let mut v:serde_json::Value=serde_json::from_slice(&message(1)).unwrap();v["pairing_generation"]="bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb".into();assert_eq!(i.submit(&serde_json::to_vec(&v).unwrap(),NOW,&mut m),Err(Error::Generation));}
#[test] fn persistence_failure_does_not_advance_checkpoint() {let mut m=Memory::default();let mut i=Ingress::new(GENERATION,&m).unwrap();m.fail=true;assert_eq!(i.submit(&message(1),NOW,&mut m),Err(Error::Io));m.fail=false;assert!(i.submit(&message(1),NOW,&mut m).is_ok());}
#[test] fn expiration_keeps_replay_checkpoint() {let mut m=Memory::default();let mut i=Ingress::new(GENERATION,&m).unwrap();i.submit(&message(1),NOW,&mut m).unwrap();assert!(i.expire(NOW+TTL_MS+1,&mut m).unwrap());assert!(i.latest().is_none());let mut reopened=Ingress::new(GENERATION,&m).unwrap();assert_eq!(reopened.submit(&message(1),NOW,&mut m),Err(Error::Replay));}
#[test] fn cache_has_no_account_url_or_credentials() {let mut m=Memory::default();let mut i=Ingress::new(GENERATION,&m).unwrap();i.submit(&message(1),NOW,&mut m).unwrap();let text=serde_json::to_string(m.data.as_ref().unwrap()).unwrap();for key in ["email","token","cookie","profile","url","password"] {assert!(!text.contains(key));}}
#[test] fn browser_cannot_choose_file_path() {let mut m=Memory::default();let mut i=Ingress::new(GENERATION,&m).unwrap();let mut v:serde_json::Value=serde_json::from_slice(&message(1)).unwrap();v["path"]="fictional.json".into();assert_eq!(i.submit(&serde_json::to_vec(&v).unwrap(),NOW,&mut m),Err(Error::InvalidJson));}
#[test] fn file_cache_roundtrip_and_atomic_replace() {let t=Temp::new();let mut store=FileStore::new(t.paths()).unwrap();let mut i=Ingress::new(GENERATION,&store).unwrap();i.submit(&message(1),NOW,&mut store).unwrap();i.submit(&message(2),NOW+100,&mut store).unwrap();let reopened=Ingress::new(GENERATION,&store).unwrap();assert_eq!(reopened.latest().unwrap().snapshot.observed_at_ms,NOW);}
#[test] fn corrupt_cache_is_not_treated_as_empty() {let t=Temp::new();let p=t.paths();std::fs::write(p.cache().join("gemini-state.json"),b"broken").unwrap();let store=FileStore::new(p).unwrap();assert!(Ingress::new(GENERATION,&store).is_err());}
